import{z as o,x as s,o as e,c as d,q as i,j as n,D as A,d as B,s as r,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"现场实验","description":"","frontmatter":{"title":"现场实验","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bx-field-experiments.md","filePath":"econ/bx-field-experiments.md","lastUpdated":1791413859000}'),p={name:"econ/bx-field-experiments.md"};function m(D,E,T,u,C,F){const t=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=i('<h1 id="现场实验" tabindex="-1">现场实验 <a class="header-anchor" href="#现场实验" aria-label="Permalink to &quot;现场实验&quot;">​</a></h1><div class="epigraph"><p>实验室买控制，田野买环境；现场实验把同一套随机化搬到真实决策的门口，付款方式是控制度的让步。</p><footer>—— 据 Harrison and List, Journal of Economic Literature, 2004；DellaVigna, Journal of Economic Literature, 2009 整理</footer></div><p><a href="/econ/bx-experiment-design">上一课</a>把实验室协议钉成五步：处理结构、随机化、激励、功效、预注册；随机化的逻辑在黑板与田野是同一套。本课把装置搬出实验室。缺口有二：行为参数离开学生被试池与简化博弈之后还剩多少，以及现场不可控时随机化的纯度怎么保。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实验室有三重折扣：被试（学生）、情境（低额与假设性）、选择集（简化树）。这不是洁癖问题，是外推折价：默认选项的力量在实验室框架效应里只是影子，在退休储蓄里是几十个百分点的参与率；歧视在问卷里测态度，在简历投递里测回电。把随机化带进现场，会撞上实验室没有的三个敌人：选择进入（被试决定是否参与处理）、流失（处理中途退出）、溢出（控制组模仿处理组）。任何一个不设防，估计就带上同号偏——选择进入让 volunteer bias 伪装成效应，流失让最不配合的人从分母里消失，溢出把处理组的效果稀释进对照。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Harrison–List 的谱系按三个维度切：被试是否学生、任务是否真实情境、被试是否知情。人工田野实验换被试不换任务；框架田野实验保留真实情境的任务；自然田野实验里被试不知道自己在实验中。设计沿用上一课五步，现场另加两条纪律。其一，随机化在门槛之前做，分析按随机化组别走（intent-to-treat）：拒绝入组与中途流失都计入原组，选择进入才不会伪装成效应；想谈「参与者身上的效应」，要另配工具变量并报第一阶段强度。其二，知情度与真实度做交换：越自然，情境污染越全，机制归因越弱——谱系不是荣誉阶梯，是控制力对真实度的价目表。</p><p><span class="marginnote">术语翻译：intent-to-treat（ITT）就是「按发牌分析」——不管你打没打这手牌，都算在你被发的组里。它保住的是随机化的纯度；想问「真打牌的人效果如何」，得另借工具变量这根拐杖，并报第一阶段强度。</span></p>',8)),(e(),n(l,null,{default:A(()=>[r(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAB%5B%22%E5%AE%9E%E9%AA%8C%E5%AE%A4%3A%20%E5%AD%A6%E7%94%9F%E5%8A%A0%E7%AE%80%E5%8C%96%E5%8D%9A%E5%BC%88%22%5D%20--%3E%20ART%5B%22%E4%BA%BA%E5%B7%A5%E7%94%B0%E9%87%8E%3A%20%E6%8D%A2%E8%A2%AB%E8%AF%95%E4%B8%8D%E6%8D%A2%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20ART%20--%3E%20FRM%5B%22%E6%A1%86%E6%9E%B6%E7%94%B0%E9%87%8E%3A%20%E7%9C%9F%E5%AE%9E%E6%83%85%E5%A2%83%E7%9A%84%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20FRM%20--%3E%20NAT%5B%22%E8%87%AA%E7%84%B6%E7%94%B0%E9%87%8E%3A%20%E8%A2%AB%E8%AF%95%E4%B8%8D%E7%9F%A5%E6%83%85%22%5D%0A%20%20LAB%20--%3E%20ITT%5B%22%E9%9A%8F%E6%9C%BA%E5%8C%96%E5%9C%A8%E9%97%A8%E6%A7%9B%E5%89%8D%2C%20%E6%8C%89%E7%BB%84%E5%88%AB%E5%88%86%E6%9E%90%22%5D%0A%20%20NAT%20--%3E%20ITT%0A%20%20ITT%20--%3E%20PRICE%5B%22%E6%8E%A7%E5%88%B6%E5%BA%A6%E6%8D%A2%E7%9C%9F%E5%AE%9E%E5%BA%A6%2C%20%E6%9C%BA%E5%88%B6%E5%BD%92%E5%9B%A0%E9%80%92%E5%87%8F%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"现场实验的机制角色是给实验室参数做压力测试。401(k) 自动加入：默认从 opt-in 改成 opt-out，参与率从不足五成跳到八成以上——默认同时改切换成本与参考点，量级远超实验室的框架效应。简历审计：随机在简历上放白人或黑人名字，白人名字的面试回电率高约五成——态度测量给不出这个数。DellaVigna 2009 的整理口径可以当换算表用：方向大体保住，量级普遍缩水；例外是现时偏差与默认效应（现场量级可观）与风险态度（实验室参数到现场最不稳）。对外端口是政策评估：同一套随机化，问题从「机制是否存在」换成「政策效应多大」，功效、成本、合规率从技术细节升为约束。不这么做会错在哪：只用实验室参数给政策定价，默认效应的量级会错开一个数量级；只用现场黑箱结果，换一个环境就失效——机制没被测过。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"Harrison–List 的分类学按「被试、任务、知情」三维切，同一项研究的落点可以移动：同一份简历审计，对投递者知情是框架田野，对雇主不知情是自然田野。报告里写清三个维度，读者才能给结论标价。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"数字实例：Madrian–Shea 的 401(k) 研究里，默认从「主动加入」改成「自动加入、不想要再退出」，新员工参与率从不足五成跳到八成以上。同样的人、同样的补贴，只换了选项的起点——这是实验室框架效应在田野放大的标尺。")],-1)),(e(),n(l,null,{default:A(()=>[r(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20RCT%5B%22%E7%8E%B0%E5%9C%BA%E9%9A%8F%E6%9C%BA%E5%8C%96%E5%88%86%E7%BB%84%22%5D%20--%3E%20SEL%5B%22%E9%80%89%E6%8B%A9%E8%BF%9B%E5%85%A5%3A%20%E7%83%AD%E5%BF%83%E8%80%85%E6%89%8D%E6%8E%A5%E5%8F%97%E5%A4%84%E7%90%86%22%5D%0A%20%20RCT%20--%3E%20ATT%5B%22%E6%B5%81%E5%A4%B1%3A%20%E4%B8%8D%E9%85%8D%E5%90%88%E8%80%85%E4%B8%AD%E9%80%94%E9%80%80%E5%87%BA%22%5D%0A%20%20RCT%20--%3E%20SPO%5B%22%E6%BA%A2%E5%87%BA%3A%20%E5%AF%B9%E7%85%A7%E7%BB%84%E6%A8%A1%E4%BB%BF%E5%A4%84%E7%90%86%E7%BB%84%22%5D%0A%20%20SEL%20--%3E%20B1%5B%22%E5%81%8F%E5%B7%AE%3A%20%E5%BF%97%E6%84%BF%E8%80%85%E7%B4%A0%E8%B4%A8%E4%BC%AA%E8%A3%85%E6%88%90%E5%A4%84%E7%90%86%E6%95%88%E5%BA%94%22%5D%0A%20%20ATT%20--%3E%20B2%5B%22%E5%81%8F%E5%B7%AE%3A%20%E5%88%86%E6%AF%8D%E8%A2%AB%E7%AD%9B%E6%88%90%E5%B9%B8%E5%AD%98%E8%80%85%22%5D%0A%20%20SPO%20--%3E%20B3%5B%22%E5%81%8F%E5%B7%AE%3A%20%E7%BB%84%E9%97%B4%E5%B7%AE%E8%B7%9D%E8%A2%AB%E7%A8%80%E9%87%8A%22%5D%0A%20%20FIX%5B%22%E8%AE%BE%E9%98%B2%3A%20ITT%20%E6%8C%89%E5%8E%9F%E7%BB%84%E5%88%86%E6%9E%90%2C%20%E9%9A%8F%E6%9C%BA%E5%8C%96%E5%8D%95%E4%BD%8D%E6%8F%90%E5%88%B0%E6%BA%A2%E5%87%BA%E8%BE%B9%E7%95%8C%E5%A4%96%22%5D%20-.-%3E%20SEL%0A%20%20FIX%20-.-%3E%20ATT%0A%20%20FIX%20-.-%3E%20SPO%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=i('<p>这张图回答的是：随机化出了实验室，三个敌人各自从哪个方向推偏估计——三个箭头都朝同号偏（夸大效应）或稀释方向走。ITT 不是统计偏好，而是把这三条渗漏通道在分析规则里提前堵死的工程决定。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>自然田野不知道机制，人工田野环境不真，两端各有用途、不互替。溢出在社交网络里最难防：一人改默认，全家模仿——处理溢出要把随机化单位提到溢出边界之上，功效随之下降。被试不知情涉及伦理：豁免知情同意要有独立审批，不能由研究者自裁。准实验（DiD、断点）与本课的分工是「研究者是否控制随机化」；政策数据上的准实验评估不属本课范围。后课默认：引用行为参数，先问它在谱系哪一格；上政策之前，先过现场再谈量级。</p><p><span class="marginnote">直觉类比：溢出像给半个班发了参考答案——期末比较「发答案班」与「没发班」的分数，差距自然被低估，因为没发的班也在抄。把随机化单位从个人提到班级，就是把溢出关进边界里，代价是样本单元变少、功效下降。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>谱系三维：被试、任务、知情；从实验室到自然田野，控制度与真实度此消彼长。</li><li>现场两条纪律：随机化在门槛前，按组别分析（ITT）；谈参与者效应须另配工具变量。</li><li>换算表：方向大体保住，量级普遍缩水；默认与现时偏差例外地大，风险态度最不稳。</li><li>401(k) 默认与简历审计是两个量级参照：几十个百分点的参与率与五成的回电差。</li><li>选择进入、流失、溢出是现场三敌人；协议要先设防，再采集。</li><li>出处：Harrison and List, <em>JEL</em> 2004；DellaVigna, <em>JEL</em> 2009；Madrian and Shea, <em>QJE</em> 2001；Bertrand and Mullainathan, <em>AER</em> 2004。</li></ul>',6))])}const c=o(p,[["render",m]]);export{h as __pageData,c as default};
